object.script:
frequencies = {670,671,672,667,668,669}
vals = {}
clock = 1

function onTick()
    vals[clock] = {input.getNumber(1), input.getNumber(2)}
    clock = clock % 6 + 1
    output.setNumber(32, frequencies[clock])
    for i = 1, #vals do
        output.setNumber(i*2-1, vals[i][1])
        output.setNumber(i*2, vals[i][2])
    end
end
